export function rleToSet(rows) {
  const s = new Set();
  for (const row of rows) {
    const y = row[0];
    for (let i = 1; i < row.length; i += 2) {
      for (let k = 0; k < row[i + 1]; k++) s.add(`${row[i] + k},${y}`);
    }
  }
  return s;
}

